import * as T from './vendor/three.module.min.js';
const mat=(color,roughness=.6)=>new T.MeshStandardMaterial({color,roughness});
export class HabitatView{
 constructor(container,onPlace){this.container=container;this.scene=new T.Scene();this.scene.background=new T.Color('#111b1b');this.scene.fog=new T.Fog('#111b1b',10,22);this.camera=new T.PerspectiveCamera(35,1,.1,60);this.renderer=new T.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.25;container.append(this.renderer.domElement);this.renderer.domElement.setAttribute('aria-label','三维培养皿，点击地面放置糖源');this.renderer.domElement.setAttribute('role','img');this.renderer.domElement.style.touchAction='none';
 this.scene.add(new T.HemisphereLight(0xd5ffe8,0x23332e,2));const key=new T.DirectionalLight(0xfff4d5,3);key.position.set(-3,7,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-4,right:4,top:4,bottom:-4});key.shadow.bias=-.0003;this.scene.add(key);const rim=new T.DirectionalLight(0x7ef4dc,1.7);rim.position.set(3,2,-4);this.scene.add(rim);
 const ground=new T.Mesh(new T.CylinderGeometry(3.4,3.4,.1,100),mat(0x263531,.85));ground.position.y=-.065;ground.receiveShadow=true;this.scene.add(ground);this.ground=ground;
 const plane=new T.Mesh(new T.PlaneGeometry(5.3,3.8),new T.MeshStandardMaterial({color:0x32443b,roughness:.94}));plane.rotation.x=-Math.PI/2;plane.position.y=-.008;plane.receiveShadow=true;this.scene.add(plane);
 const grid=new T.GridHelper(6,30,0x496054,0x344b40);grid.position.y=.002;grid.material.transparent=true;grid.material.opacity=.25;this.scene.add(grid);
 const rail=new T.Mesh(new T.TorusGeometry(3.2,.033,10,128),mat(0x778e7c,.2));rail.rotation.x=Math.PI/2;rail.position.y=.055;this.scene.add(rail);
 const glass=new T.Mesh(new T.CylinderGeometry(3.21,3.21,.25,100,1,true),new T.MeshPhysicalMaterial({color:0xa5d4bc,transparent:true,opacity:.13,roughness:.15,side:T.DoubleSide,depthWrite:false}));glass.position.y=.07;this.scene.add(glass);
 this.foodGroup=new T.Group();this.scene.add(this.foodGroup);this.foodMeshes=new Map();this.fly=this.makeFly();this.scene.add(this.fly);this.pathPositions=new Float32Array(2400);this.pathGeometry=new T.BufferGeometry();this.pathGeometry.setAttribute('position',new T.BufferAttribute(this.pathPositions,3));this.path=new T.Line(this.pathGeometry,new T.LineBasicMaterial({color:0xb8eb8b,transparent:true,opacity:.4}));this.scene.add(this.path);this.pathPoints=[];this.lastTrace=-1;this.setView(false);
 const ray=new T.Raycaster(),point=new T.Vector2(),floor=new T.Plane(new T.Vector3(0,1,0),0),hit=new T.Vector3();let down;
 this.renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];});this.renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>8)return;const r=this.renderer.domElement.getBoundingClientRect();point.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(point,this.camera);if(ray.ray.intersectPlane(floor,hit)&&Math.abs(hit.x)<2.5&&Math.abs(hit.z)<1.75)onPlace(hit.x,hit.z);});new ResizeObserver(()=>this.resize()).observe(container);this.resize();
 }
 makeFly(){const root=new T.Group();const abdomen=mat(0x755636,.63),thorax=mat(0x554932,.65),dark=mat(0x261f19,.65),eye=mat(0xbb432e,.35);const ellipsoid=(parent,x,y,z,sx,sy,sz,material)=>{const m=new T.Mesh(new T.SphereGeometry(1,24,16),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m;};
 ellipsoid(root,-.115,.16,0,.155,.085,.085,abdomen);ellipsoid(root,.05,.18,0,.095,.09,.09,thorax);ellipsoid(root,.16,.185,0,.066,.061,.065,thorax);
 for(let i=0;i<4;i++){const ring=new T.Mesh(new T.TorusGeometry(.066-i*.008,.009,6,30),dark);ring.rotation.y=Math.PI/2;ring.scale.y=.93;ring.position.set(-.06-i*.045,.16,0);root.add(ring);}
 for(const s of [-1,1]){ellipsoid(root,.181,.199,s*.047,.034,.047,.027,eye);const antenna=ellipsoid(root,.223,.201,s*.027,.036,.005,.006,dark);antenna.rotation.y=s*.3;}
 this.wings=[];const wingMat=new T.MeshPhysicalMaterial({color:0xe0ecd3,transparent:true,opacity:.4,roughness:.25,metalness:.05,side:T.DoubleSide,depthWrite:false});for(const s of [-1,1]){const wing=ellipsoid(root,-.08,.255,s*.07,.205,.006,.065,wingMat);wing.rotation.y=s*.28;wing.rotation.z=-.09;this.wings.push(wing);}
 this.proboscis=ellipsoid(root,.215,.15,0,.025,.012,.014,mat(0xb69568));this.legs=[];for(let pair=0;pair<3;pair++)for(const side of [-1,1]){const lineMat=mat(0x30261a);const segments=[];for(let j=0;j<3;j++){const segment=new T.Mesh(new T.CylinderGeometry(.006,.008,1,7),lineMat);segment.castShadow=true;root.add(segment);segments.push(segment);}this.legs.push({pair,side,segments});}return root;
 }
 segment(mesh,a,b){const v=new T.Vector3().subVectors(b,a);mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.scale.y=v.length();mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());}
 setView(top){this.top=top;this.camera.position.set(top?.01:4.5,top?8.8:6.3,top?.01:6.8);this.camera.lookAt(0,0,0);}
 resize(){const w=this.container.clientWidth,h=this.container.clientHeight;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}
 reset(){this.pathPoints=[];this.lastTrace=-1;}
 update(s){this.state=s;this.fly.position.set(s.x,0,s.z);this.fly.rotation.y=-s.heading;this.fly.position.y=Math.sin(s.time*24)*.005*Math.min(1,s.speed*5);this.proboscis.scale.x=.025+s.proboscis*.055;this.proboscis.position.x=.215+s.proboscis*.035;this.proboscis.position.y=.15-s.proboscis*.08;
 for(const leg of this.legs){const {pair,side,segments}=leg;const phase=s.time*(s.speed>.05?18:2)+(pair%2===0?0:Math.PI)+(side===1?Math.PI:0);const swing=Math.sin(phase)*Math.min(.06,s.speed*.25),lift=Math.max(0,Math.cos(phase))*.055*Math.min(1,s.speed*6);const x=.1-pair*.12;const a=new T.Vector3(x,.16,side*.065),b=new T.Vector3(x+(1-pair)*.06,.12,side*.16),c=new T.Vector3(x+(1-pair)*.1+swing,.045+lift,side*.23),d=new T.Vector3(x+(1-pair)*.12+swing,.01+lift,side*.28);this.segment(segments[0],a,b);this.segment(segments[1],b,c);this.segment(segments[2],c,d);}
 const ids=new Set(s.foods.map(f=>f.id));for(const [id,g] of this.foodMeshes)if(!ids.has(id)){this.foodGroup.remove(g);g.traverse(m=>{m.geometry?.dispose();m.material?.dispose();});this.foodMeshes.delete(id);}
 for(const f of s.foods){let group=this.foodMeshes.get(f.id);if(!group){group=new T.Group();const drop=new T.Mesh(new T.SphereGeometry(.13,28,16),new T.MeshPhysicalMaterial({color:0xf2b952,roughness:.2,metalness:.08,transparent:true,opacity:.88}));drop.scale.y=.35;drop.position.y=.025;drop.castShadow=true;group.add(drop);const halo=new T.Mesh(new T.RingGeometry(.2,.23,48),new T.MeshBasicMaterial({color:0xd5b15e,transparent:true,opacity:.35,side:T.DoubleSide,depthWrite:false}));halo.rotation.x=-Math.PI/2;halo.position.y=.005;group.add(halo);this.foodGroup.add(group);this.foodMeshes.set(f.id,group);}group.position.set(f.x,0,f.z);group.visible=f.amount>.001;group.children[0].scale.set(Math.max(.2,f.amount),.35*Math.max(.2,f.amount),Math.max(.2,f.amount));group.children[1].material.opacity=.22+Math.sin(s.time*2)*.08;}
 if(Math.floor(s.time*5)!==this.lastTrace){this.lastTrace=Math.floor(s.time*5);this.pathPoints.push([s.x,.008,s.z]);if(this.pathPoints.length>800)this.pathPoints.shift();this.pathPoints.forEach((p,i)=>this.pathPositions.set(p,i*3));this.pathGeometry.setDrawRange(0,this.pathPoints.length);this.pathGeometry.attributes.position.needsUpdate=true;this.pathGeometry.computeBoundingSphere();}
 }
 render(){this.renderer.render(this.scene,this.camera);}
}
